INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-belgium-mandatory-b2b-peppol', '2026-01-01', '2026-01', 'Belgium''s B2B e-invoicing mandate takes effect, requiring Peppol BIS 3.0 for all domestic VAT-registered transactions.', '<h3>🇧🇪 Belgium — mandatory B2B e-invoicing via Peppol</h3><p>Structured e-invoicing is now mandatory for domestic B2B transactions between Belgian VAT-registered businesses, using Peppol BIS Billing 3.0 / EN 16931. PDF and paper invoices no longer qualify as of today. A three-month administrative tolerance period runs until 1 April, after which a progressive penalty regime (€1,500 / €3,000 / €5,000 per infraction) applies — so this window is genuinely worth using to close any remaining gaps, not just to wait it out.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium" target="_blank" rel="noopener">🔗 Official source: EU Digital Building Blocks — Belgium</a></p>', 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-01-belgium-mandatory-b2b-peppol', id FROM countries WHERE name_en = 'Belgium';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-belgium-mandatory-b2b-peppol', 'en', 'Belgium — mandatory B2B e-invoicing via Peppol', 'Belgium''s B2B e-invoicing mandate takes effect, requiring Peppol BIS 3.0 for all domestic VAT-registered transactions.', '<h3>🇧🇪 Belgium — mandatory B2B e-invoicing via Peppol</h3><p>Structured e-invoicing is now mandatory for domestic B2B transactions between Belgian VAT-registered businesses, using Peppol BIS Billing 3.0 / EN 16931. PDF and paper invoices no longer qualify as of today. A three-month administrative tolerance period runs until 1 April, after which a progressive penalty regime (€1,500 / €3,000 / €5,000 per infraction) applies — so this window is genuinely worth using to close any remaining gaps, not just to wait it out.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium" target="_blank" rel="noopener">🔗 Official source: EU Digital Building Blocks — Belgium</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-malaysia-myinvois-phase-4', '2026-01-01', '2026-01', 'MyInvois Phase 4 brings businesses with RM1–5 million turnover into Malaysia''s e-invoicing mandate.', '<h3>🇲🇾 Malaysia — MyInvois Phase 4 begins</h3><p>Businesses with annual turnover between RM1 million and RM5 million enter the mandate today, with a relaxation period on submission-error penalties running through to the end of 2027. Individual e-invoices above RM10,000 are now mandatory — consolidated invoicing is no longer permitted for amounts at that level.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Official source: LHDN — MyInvois / e-Invoice</a></p>', 'https://www.hasil.gov.my/en/e-invoice', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-01-malaysia-myinvois-phase-4', id FROM countries WHERE name_en = 'Malaysia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-malaysia-myinvois-phase-4', 'en', 'Malaysia — MyInvois Phase 4 begins', 'MyInvois Phase 4 brings businesses with RM1–5 million turnover into Malaysia''s e-invoicing mandate.', '<h3>🇲🇾 Malaysia — MyInvois Phase 4 begins</h3><p>Businesses with annual turnover between RM1 million and RM5 million enter the mandate today, with a relaxation period on submission-error penalties running through to the end of 2027. Individual e-invoices above RM10,000 are now mandatory — consolidated invoicing is no longer permitted for amounts at that level.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Official source: LHDN — MyInvois / e-Invoice</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-brazil-cbs-ibs-test-fields', '2026-01-01', '2026-01', 'Brazil''s dual-VAT reform begins, requiring new CBS/IBS test-rate fields on NF-e, NFC-e, and NFS-e documents.', '<h3>🇧🇷 Brazil — CBS/IBS test fields required</h3><p>As Brazil''s dual-VAT reform begins, electronic tax documents (NF-e, NFC-e, NFS-e) must now include the new CBS and IBS fields at test rates of 0.9% and 0.1% respectively. There''s no financial impact yet at these test rates, but the legal obligation to include the data correctly already applies — and validation tightens considerably from April.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Official source: Portal Nacional da NF-e (SEFAZ)</a></p>', 'https://www.nfe.fazenda.gov.br/portal/principal.aspx', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-01-brazil-cbs-ibs-test-fields', id FROM countries WHERE name_en = 'Brazil';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-brazil-cbs-ibs-test-fields', 'en', 'Brazil — CBS/IBS test fields required', 'Brazil''s dual-VAT reform begins, requiring new CBS/IBS test-rate fields on NF-e, NFC-e, and NFS-e documents.', '<h3>🇧🇷 Brazil — CBS/IBS test fields required</h3><p>As Brazil''s dual-VAT reform begins, electronic tax documents (NF-e, NFC-e, NFS-e) must now include the new CBS and IBS fields at test rates of 0.9% and 0.1% respectively. There''s no financial impact yet at these test rates, but the legal obligation to include the data correctly already applies — and validation tightens considerably from April.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Official source: Portal Nacional da NF-e (SEFAZ)</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-mexico-2026-tax-reform', '2026-01-01', '2026-01', 'Mexico''s 2026 tax reform strengthens SAT''s enforcement powers, introducing criminal liability for false CFDIs.', '<h3>🇲🇽 Mexico — 2026 tax reform takes effect</h3><p>SAT''s enforcement powers strengthen from today, adding stricter authenticity checks and — notably — new criminal liability for false or simulated CFDIs. This is a meaningful escalation from the previous purely administrative penalty framework. Worth reviewing your defense documentation and cancellation procedures now, given SAT can request supporting evidence within just 5 business days.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sat.gob.mx" target="_blank" rel="noopener">🔗 Official source: SAT — Servicio de Administración Tributaria</a></p>', 'https://www.sat.gob.mx', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-01-mexico-2026-tax-reform', id FROM countries WHERE name_en = 'Mexico';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-mexico-2026-tax-reform', 'en', 'Mexico — 2026 tax reform takes effect', 'Mexico''s 2026 tax reform strengthens SAT''s enforcement powers, introducing criminal liability for false CFDIs.', '<h3>🇲🇽 Mexico — 2026 tax reform takes effect</h3><p>SAT''s enforcement powers strengthen from today, adding stricter authenticity checks and — notably — new criminal liability for false or simulated CFDIs. This is a meaningful escalation from the previous purely administrative penalty framework. Worth reviewing your defense documentation and cancellation procedures now, given SAT can request supporting evidence within just 5 business days.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sat.gob.mx" target="_blank" rel="noopener">🔗 Official source: SAT — Servicio de Administración Tributaria</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-new-zealand-agency-einvoicing', '2026-01-01', '2026-01', 'High-volume New Zealand government agencies must now send and receive e-invoices in the PINT A-NZ format.', '<h3>🇳🇿 New Zealand — high-volume government agencies must send and receive e-invoices</h3><p>Agencies processing more than 2,000 domestic trade invoices annually must now be fully capable of both sending and receiving structured e-invoices — using the PINT A-NZ format, mandatory for government e-invoicing since May 2025 — and must pay 95% of them within 5 business days. If you supply an agency at this volume, this is the moment payment terms should actually start improving.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.einvoicing.govt.nz" target="_blank" rel="noopener">🔗 Official source: einvoicing.govt.nz — MBIE</a></p>', 'https://www.einvoicing.govt.nz', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-01-new-zealand-agency-einvoicing', id FROM countries WHERE name_en = 'New Zealand';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-new-zealand-agency-einvoicing', 'en', 'New Zealand — high-volume government agencies must send and receive e-invoices', 'High-volume New Zealand government agencies must now send and receive e-invoices in the PINT A-NZ format.', '<h3>🇳🇿 New Zealand — high-volume government agencies must send and receive e-invoices</h3><p>Agencies processing more than 2,000 domestic trade invoices annually must now be fully capable of both sending and receiving structured e-invoices — using the PINT A-NZ format, mandatory for government e-invoicing since May 2025 — and must pay 95% of them within 5 business days. If you supply an agency at this volume, this is the moment payment terms should actually start improving.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.einvoicing.govt.nz" target="_blank" rel="noopener">🔗 Official source: einvoicing.govt.nz — MBIE</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-croatia-fiskalizacija-2', '2026-01-01', '2026-01', 'Croatia''s Fiskalizacija 2.0 mandates structured B2B e-invoicing and real-time e-reporting for all VAT-registered taxpayers.', '<h3>🇭🇷 Croatia — Fiskalizacija 2.0 goes live</h3><p>Croatia''s biggest e-invoicing reform yet: structured issuance, receipt, and real-time e-reporting are now mandatory for all VAT-registered, Croatian-established taxpayers — layered on top of the B2G mandate already in force since 2019. This includes a 5-day buyer-side fiscalization workflow and monthly e-reporting by the 20th of each month, plus an 11-year archiving requirement for original XML invoices.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://porezna-uprava.gov.hr/en" target="_blank" rel="noopener">🔗 Official source: Porezna uprava (Croatian Tax Administration)</a></p><p><strong>What this means for your team:</strong> if you operate in any of these six markets, this is the moment to confirm — not assume — that whatever went live over the holidays is actually working correctly in production, not just configured and left untested.</p>', 'https://porezna-uprava.gov.hr/en', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-01-croatia-fiskalizacija-2', id FROM countries WHERE name_en = 'Croatia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-croatia-fiskalizacija-2', 'en', 'Croatia — Fiskalizacija 2.0 goes live', 'Croatia''s Fiskalizacija 2.0 mandates structured B2B e-invoicing and real-time e-reporting for all VAT-registered taxpayers.', '<h3>🇭🇷 Croatia — Fiskalizacija 2.0 goes live</h3><p>Croatia''s biggest e-invoicing reform yet: structured issuance, receipt, and real-time e-reporting are now mandatory for all VAT-registered, Croatian-established taxpayers — layered on top of the B2G mandate already in force since 2019. This includes a 5-day buyer-side fiscalization workflow and monthly e-reporting by the 20th of each month, plus an 11-year archiving requirement for original XML invoices.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://porezna-uprava.gov.hr/en" target="_blank" rel="noopener">🔗 Official source: Porezna uprava (Croatian Tax Administration)</a></p><p><strong>What this means for your team:</strong> if you operate in any of these six markets, this is the moment to confirm — not assume — that whatever went live over the holidays is actually working correctly in production, not just configured and left untested.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-02-01-poland-ksef-large-taxpayers', '2026-02-01', '2026-02', 'Poland''s KSeF clearance platform becomes mandatory for large taxpayers with turnover above PLN 200 million.', '<h3>🇵🇱 Poland — KSeF mandatory for large taxpayers</h3><p>Large taxpayers with turnover above PLN 200 million became the first group required to issue B2B invoices through the Krajowy System e-Faktur (KSeF) clearance platform today. This is a genuine clearance model — an invoice carries no legal effect until KSeF has validated and cleared it, using the FA(3) XML schema submitted via API. Everyone else follows in April, and micro-entrepreneurs from January 2027; Poland is deliberately phasing this in by taxpayer size rather than switching on all at once, which is worth knowing if you''re a smaller business assuming you''re already in scope.</p><p><strong>What this means for your team:</strong> if you''re a large Polish taxpayer, this is no longer a planning exercise. Confirm your API integration with KSeF is actually live, and that staff and any third-party issuer authorisations are properly configured — a misconfigured authorisation is one of the more common reasons clearance fails silently in the first weeks.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Official source: KSeF — Ministry of Finance</a></p>', 'https://ksef.mf.gov.pl/', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-02-01-poland-ksef-large-taxpayers', id FROM countries WHERE name_en = 'Poland';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-poland-ksef-large-taxpayers', 'en', 'Poland — KSeF mandatory for large taxpayers', 'Poland''s KSeF clearance platform becomes mandatory for large taxpayers with turnover above PLN 200 million.', '<h3>🇵🇱 Poland — KSeF mandatory for large taxpayers</h3><p>Large taxpayers with turnover above PLN 200 million became the first group required to issue B2B invoices through the Krajowy System e-Faktur (KSeF) clearance platform today. This is a genuine clearance model — an invoice carries no legal effect until KSeF has validated and cleared it, using the FA(3) XML schema submitted via API. Everyone else follows in April, and micro-entrepreneurs from January 2027; Poland is deliberately phasing this in by taxpayer size rather than switching on all at once, which is worth knowing if you''re a smaller business assuming you''re already in scope.</p><p><strong>What this means for your team:</strong> if you''re a large Polish taxpayer, this is no longer a planning exercise. Confirm your API integration with KSeF is actually live, and that staff and any third-party issuer authorisations are properly configured — a misconfigured authorisation is one of the more common reasons clearance fails silently in the first weeks.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Official source: KSeF — Ministry of Finance</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-02-01-belgium-croatia-january-check-in', '2026-02-01', '2026-02', 'A follow-up check-in on January''s Belgium and Croatia mandates, with a reminder to test integrations end-to-end, not just confirm connectivity.', '<h3>Checking in on January</h3><p>A quick follow-up on last month''s six-country cluster: if you''re operating in Belgium or Croatia and haven''t yet tested your integration end-to-end — not just confirmed it''s technically connected — this is a good month to do it. Both mandates carry real penalties for gaps that only surface once genuine invoice volume starts flowing through them, rather than in a sandbox test.</p>', NULL, 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-02-01-belgium-croatia-january-check-in', id FROM countries WHERE name_en = 'Belgium';
INSERT INTO story_countries (story_id, country_id) SELECT '2026-02-01-belgium-croatia-january-check-in', id FROM countries WHERE name_en = 'Croatia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-belgium-croatia-january-check-in', 'en', 'Checking in on January', 'A follow-up check-in on January''s Belgium and Croatia mandates, with a reminder to test integrations end-to-end, not just confirm connectivity.', '<h3>Checking in on January</h3><p>A quick follow-up on last month''s six-country cluster: if you''re operating in Belgium or Croatia and haven''t yet tested your integration end-to-end — not just confirmed it''s technically connected — this is a good month to do it. Both mandates carry real penalties for gaps that only surface once genuine invoice volume starts flowing through them, rather than in a sandbox test.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-01-saudi-arabia-zatca-wave-23', '2026-03-01', '2026-03', 'ZATCA''s Wave 23 brings businesses above SAR 750,000 turnover into Fatoora''s real-time clearance requirements.', '<h3>🇸🇦 Saudi Arabia — ZATCA Fatoora Wave 23</h3><p>Businesses with VAT-taxable turnover above SAR 750,000 in 2022, 2023, or 2024 were required to complete Phase 2 integration with the Fatoora platform for real-time clearance from today — meaning invoices carry a UUID, QR code, and cryptographic stamp, submitted via API for real-time B2B/B2G clearance. ZATCA continues its wave-based rollout — Wave 24 follows in June, dropping the threshold to SAR 375,000 and bringing in nearly every VAT-registered business in the country.</p><p><strong>What this means for your team:</strong> if your turnover crossed SAR 750,000 in any of those three reference years, assume you''re in Wave 23 unless ZATCA has told you otherwise — direct notification typically arrives around six months ahead, so if you haven''t heard anything and think you should have, it''s worth checking proactively rather than waiting for a letter that may already be delayed.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://zatca.gov.sa" target="_blank" rel="noopener">🔗 Official source: ZATCA — Fatoora</a></p>', 'https://zatca.gov.sa', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-01-saudi-arabia-zatca-wave-23', id FROM countries WHERE name_en = 'Saudi Arabia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-saudi-arabia-zatca-wave-23', 'en', 'Saudi Arabia — ZATCA Fatoora Wave 23', 'ZATCA''s Wave 23 brings businesses above SAR 750,000 turnover into Fatoora''s real-time clearance requirements.', '<h3>🇸🇦 Saudi Arabia — ZATCA Fatoora Wave 23</h3><p>Businesses with VAT-taxable turnover above SAR 750,000 in 2022, 2023, or 2024 were required to complete Phase 2 integration with the Fatoora platform for real-time clearance from today — meaning invoices carry a UUID, QR code, and cryptographic stamp, submitted via API for real-time B2B/B2G clearance. ZATCA continues its wave-based rollout — Wave 24 follows in June, dropping the threshold to SAR 375,000 and bringing in nearly every VAT-registered business in the country.</p><p><strong>What this means for your team:</strong> if your turnover crossed SAR 750,000 in any of those three reference years, assume you''re in Wave 23 unless ZATCA has told you otherwise — direct notification typically arrives around six months ahead, so if you haven''t heard anything and think you should have, it''s worth checking proactively rather than waiting for a letter that may already be delayed.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://zatca.gov.sa" target="_blank" rel="noopener">🔗 Official source: ZATCA — Fatoora</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-01-chile-digital-boleta-delivery', '2026-03-01', '2026-03', 'Chile now requires digital delivery of the boleta electrónica for businesses without point-of-sale printing capability.', '<h3>🇨🇱 Chile — digital delivery required without a printer</h3><p>Businesses without point-of-sale printing capability must now deliver the <em>boleta electrónica</em> digitally — by email, SMS, WhatsApp, QR code, or an equivalent electronic channel — rather than simply skipping delivery. A small rule, but one that closes a real gap for mobile vendors, pop-ups, and delivery-only operations that previously had no clearly compliant path when they lacked a physical printer.</p><p><strong>What this means for your team:</strong> if you run any point-of-sale operation without a physical printer — markets, pop-ups, delivery-only setups — confirm you actually have one of these electronic channels working today, not just planned for later. Businesses that do have printers must generally still deliver the printed representation as before.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sii.cl" target="_blank" rel="noopener">🔗 Official source: Servicio de Impuestos Internos (SII)</a></p>', 'https://www.sii.cl', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-01-chile-digital-boleta-delivery', id FROM countries WHERE name_en = 'Chile';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-chile-digital-boleta-delivery', 'en', 'Chile — digital delivery required without a printer', 'Chile now requires digital delivery of the boleta electrónica for businesses without point-of-sale printing capability.', '<h3>🇨🇱 Chile — digital delivery required without a printer</h3><p>Businesses without point-of-sale printing capability must now deliver the <em>boleta electrónica</em> digitally — by email, SMS, WhatsApp, QR code, or an equivalent electronic channel — rather than simply skipping delivery. A small rule, but one that closes a real gap for mobile vendors, pop-ups, and delivery-only operations that previously had no clearly compliant path when they lacked a physical printer.</p><p><strong>What this means for your team:</strong> if you run any point-of-sale operation without a physical printer — markets, pop-ups, delivery-only setups — confirm you actually have one of these electronic channels working today, not just planned for later. Businesses that do have printers must generally still deliver the printed representation as before.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sii.cl" target="_blank" rel="noopener">🔗 Official source: Servicio de Impuestos Internos (SII)</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-04-01-poland-ksef-universal', '2026-04-01', '2026-04', 'Poland''s KSeF mandate goes universal for VAT-registered businesses, retiring the old-style correction note process entirely.', '<h3>🇵🇱 Poland — KSeF mandate goes universal</h3><p>From today, Poland''s KSeF requirement extends to essentially every remaining VAT-registered business (micro-entrepreneurs are still on a separate track, joining from January 2027). From this date, an invoice only carries legal force once KSeF has cleared it — and the old-style correction notes (<em>noty korygujące</em>) are no longer valid at all; corrections now have to go through KSeF''s own structured correction process.</p><p><strong>What this means for your team:</strong> if you have any Polish B2B invoicing flow that was previously exempt, confirm your system is actually generating valid FA(3) structured invoices now, not just planning to by year-end. Also worth double-checking: from 1 August 2026, KSeF invoice numbers need to appear on bank transfer references too — a small detail that''s easy for a treasury team to miss if they weren''t looped into the e-invoicing rollout.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Official source: KSeF — Ministry of Finance</a></p>', 'https://ksef.mf.gov.pl/', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-04-01-poland-ksef-universal', id FROM countries WHERE name_en = 'Poland';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-poland-ksef-universal', 'en', 'Poland — KSeF mandate goes universal', 'Poland''s KSeF mandate goes universal for VAT-registered businesses, retiring the old-style correction note process entirely.', '<h3>🇵🇱 Poland — KSeF mandate goes universal</h3><p>From today, Poland''s KSeF requirement extends to essentially every remaining VAT-registered business (micro-entrepreneurs are still on a separate track, joining from January 2027). From this date, an invoice only carries legal force once KSeF has cleared it — and the old-style correction notes (<em>noty korygujące</em>) are no longer valid at all; corrections now have to go through KSeF''s own structured correction process.</p><p><strong>What this means for your team:</strong> if you have any Polish B2B invoicing flow that was previously exempt, confirm your system is actually generating valid FA(3) structured invoices now, not just planning to by year-end. Also worth double-checking: from 1 August 2026, KSeF invoice numbers need to appear on bank transfer references too — a small detail that''s easy for a treasury team to miss if they weren''t looped into the e-invoicing rollout.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Official source: KSeF — Ministry of Finance</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-04-01-brazil-cbs-ibs-validation', '2026-04-01', '2026-04', 'Brazil begins rigorously validating CBS/IBS tax fields, risking automatic rejection of invoices with missing or inconsistent data.', '<h3>🇧🇷 Brazil — CBS/IBS validation begins</h3><p>As Brazil''s dual-VAT reform progresses, authorization systems started rigorously validating the new CBS and IBS tax fields on NF-e, NFC-e, and NFS-e documents today. Invoices with missing or inconsistent data now risk automatic rejection — still at test rates (0.9% / 0.1%), so no financial impact yet, but a rejected invoice can still hold up the movement of goods regardless of the rate being nominal.</p><p><strong>What this means for your team:</strong> if you haven''t already, audit your invoice output for complete CBS/IBS/IS data groups now, while the stakes are still low — waiting until the rates go fully live in August, per Technical Note 2025.002-RTC, is cutting it close.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Official source: Portal Nacional da NF-e (SEFAZ)</a></p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Full technical detail on both of these lives in their respective Deep Dives — Poland and Brazil — if you need the complete picture for a briefing.</p>', 'https://www.nfe.fazenda.gov.br/portal/principal.aspx', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-04-01-brazil-cbs-ibs-validation', id FROM countries WHERE name_en = 'Brazil';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-brazil-cbs-ibs-validation', 'en', 'Brazil — CBS/IBS validation begins', 'Brazil begins rigorously validating CBS/IBS tax fields, risking automatic rejection of invoices with missing or inconsistent data.', '<h3>🇧🇷 Brazil — CBS/IBS validation begins</h3><p>As Brazil''s dual-VAT reform progresses, authorization systems started rigorously validating the new CBS and IBS tax fields on NF-e, NFC-e, and NFS-e documents today. Invoices with missing or inconsistent data now risk automatic rejection — still at test rates (0.9% / 0.1%), so no financial impact yet, but a rejected invoice can still hold up the movement of goods regardless of the rate being nominal.</p><p><strong>What this means for your team:</strong> if you haven''t already, audit your invoice output for complete CBS/IBS/IS data groups now, while the stakes are still low — waiting until the rates go fully live in August, per Technical Note 2025.002-RTC, is cutting it close.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Official source: Portal Nacional da NF-e (SEFAZ)</a></p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Full technical detail on both of these lives in their respective Deep Dives — Poland and Brazil — if you need the complete picture for a briefing.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-01-slovakia-voluntary-testing', '2026-05-01', '2026-05', 'Slovakia opens voluntary testing of its distinctive 5-corner Digital Postman network ahead of its January 2027 mandate.', '<h3>🇸🇰 Slovakia — voluntary transition period begins</h3><p>Businesses can now register to voluntarily test structured e-invoicing and reporting ahead of Slovakia''s January 2027 mandate, using the country''s distinctive decentralised "5-corner" model built on certified <em>Digital Postman</em> access points running over Peppol — a variant we don''t see replicated exactly anywhere else we track.</p><p><strong>What this means for your team:</strong> if you trade with Slovak VAT taxpayers, this is genuinely worth doing early rather than waiting. From 2027, input VAT deductions can''t be claimed on non-compliant incoming invoices — a real cash-flow consequence, not just a paperwork one. Testing now, while there''s no penalty for getting it wrong, is the cheap way to find integration problems before they cost you money.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.financnasprava.sk/en/homepage" target="_blank" rel="noopener">🔗 Official source: Financial Administration of the Slovak Republic</a></p>', 'https://www.financnasprava.sk/en/homepage', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-01-slovakia-voluntary-testing', id FROM countries WHERE name_en = 'Slovakia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-slovakia-voluntary-testing', 'en', 'Slovakia — voluntary transition period begins', 'Slovakia opens voluntary testing of its distinctive 5-corner Digital Postman network ahead of its January 2027 mandate.', '<h3>🇸🇰 Slovakia — voluntary transition period begins</h3><p>Businesses can now register to voluntarily test structured e-invoicing and reporting ahead of Slovakia''s January 2027 mandate, using the country''s distinctive decentralised "5-corner" model built on certified <em>Digital Postman</em> access points running over Peppol — a variant we don''t see replicated exactly anywhere else we track.</p><p><strong>What this means for your team:</strong> if you trade with Slovak VAT taxpayers, this is genuinely worth doing early rather than waiting. From 2027, input VAT deductions can''t be claimed on non-compliant incoming invoices — a real cash-flow consequence, not just a paperwork one. Testing now, while there''s no penalty for getting it wrong, is the cheap way to find integration problems before they cost you money.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.financnasprava.sk/en/homepage" target="_blank" rel="noopener">🔗 Official source: Financial Administration of the Slovak Republic</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-01-2027-wave-multi-country-outlook', '2026-05-01', '2026-05', 'A look ahead at the January 2027 wave, as Poland''s remaining taxpayers, Spain''s VeriFactu rollout, and the UAE''s Phase 1 mandate all converge on the same go-live window.', '<h3>Looking ahead: the 2027 wave is coming into focus</h3><p>Slovakia isn''t alone — Poland''s remaining micro-entrepreneurs, Spain''s VeriFactu rollout, and the UAE''s Phase 1 mandate are all also targeting January 2027 go-lives. If your business touches more than one of these markets, this is a reasonable point to start a shared readiness assessment across all of them rather than treating each as a separate fire drill later in the year.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">If you haven''t seen it yet, "Preparing for a Mandate" under the Education menu walks through exactly this kind of multi-country planning.</p>', NULL, 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-01-2027-wave-multi-country-outlook', id FROM countries WHERE name_en = 'Poland';
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-01-2027-wave-multi-country-outlook', id FROM countries WHERE name_en = 'Spain';
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-01-2027-wave-multi-country-outlook', id FROM countries WHERE name_en = 'United Arab Emirates';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-2027-wave-multi-country-outlook', 'en', 'Looking ahead: the 2027 wave is coming into focus', 'A look ahead at the January 2027 wave, as Poland''s remaining taxpayers, Spain''s VeriFactu rollout, and the UAE''s Phase 1 mandate all converge on the same go-live window.', '<h3>Looking ahead: the 2027 wave is coming into focus</h3><p>Slovakia isn''t alone — Poland''s remaining micro-entrepreneurs, Spain''s VeriFactu rollout, and the UAE''s Phase 1 mandate are all also targeting January 2027 go-lives. If your business touches more than one of these markets, this is a reasonable point to start a shared readiness assessment across all of them rather than treating each as a separate fire drill later in the year.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">If you haven''t seen it yet, "Preparing for a Mandate" under the Education menu walks through exactly this kind of multi-country planning.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-01-australia-peppol-threshold-preview', '2026-06-01', '2026-06', 'Australia''s 30% Peppol threshold for federal invoices takes effect 1 July — a preview of what''s coming and what to check beforehand.', '<h3>🇦🇺 Australia — 30% Peppol threshold for federal invoices</h3><p>From 1 July, Non-Corporate Commonwealth Entities must have at least 30% of received supplier invoices flowing through the Peppol network, on the way to full automation by December, with quarterly progress reporting to the Australian Peppol Authority. If you supply Australian federal agencies, this is a good moment to confirm your invoicing is actually Peppol-enabled using the PINT A-NZ format — the only standard supported since May 2025 — not just technically capable of it.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Official source: ATO — About eInvoicing</a></p>', 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-01-australia-peppol-threshold-preview', id FROM countries WHERE name_en = 'Australia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-australia-peppol-threshold-preview', 'en', 'Australia — 30% Peppol threshold for federal invoices', 'Australia''s 30% Peppol threshold for federal invoices takes effect 1 July — a preview of what''s coming and what to check beforehand.', '<h3>🇦🇺 Australia — 30% Peppol threshold for federal invoices</h3><p>From 1 July, Non-Corporate Commonwealth Entities must have at least 30% of received supplier invoices flowing through the Peppol network, on the way to full automation by December, with quarterly progress reporting to the Australian Peppol Authority. If you supply Australian federal agencies, this is a good moment to confirm your invoicing is actually Peppol-enabled using the PINT A-NZ format — the only standard supported since May 2025 — not just technically capable of it.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Official source: ATO — About eInvoicing</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-01-denmark-small-business-bookkeeping-preview', '2026-06-01', '2026-06', 'Denmark''s Bookkeeping Act digital requirements extend to small businesses on custom systems from 1 July — worth checking your turnover against the threshold now.', '<h3>🇩🇰 Denmark — small businesses on custom systems join the mandate</h3><p>Small businesses and sole proprietorships exceeding DKK 300,000 turnover in two consecutive years, using non-registered ("custom") accounting systems, become fully subject to the Bookkeeping Act''s digital requirements. Worth checking whether your turnover has actually crossed that threshold in the last two fiscal years — it''s easy to assume you''re still under it without actually checking the numbers.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Official source: Erhvervsstyrelsen (Danish Business Authority)</a></p>', 'https://erhvervsstyrelsen.dk', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-01-denmark-small-business-bookkeeping-preview', id FROM countries WHERE name_en = 'Denmark';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-denmark-small-business-bookkeeping-preview', 'en', 'Denmark — small businesses on custom systems join the mandate', 'Denmark''s Bookkeeping Act digital requirements extend to small businesses on custom systems from 1 July — worth checking your turnover against the threshold now.', '<h3>🇩🇰 Denmark — small businesses on custom systems join the mandate</h3><p>Small businesses and sole proprietorships exceeding DKK 300,000 turnover in two consecutive years, using non-registered ("custom") accounting systems, become fully subject to the Bookkeeping Act''s digital requirements. Worth checking whether your turnover has actually crossed that threshold in the last two fiscal years — it''s easy to assume you''re still under it without actually checking the numbers.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Official source: Erhvervsstyrelsen (Danish Business Authority)</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-01-malaysia-related-company-rule-preview', '2026-06-01', '2026-06', 'Malaysia''s MyInvois related-company rule takes effect 1 July, catching subsidiaries of RM1 million+ groups regardless of their own individual revenue.', '<h3>🇲🇾 Malaysia — related companies of RM1m+ groups now in scope</h3><p>Here''s the one most likely to catch a business off guard: even if your own revenue is well under Malaysia''s thresholds, if you''re a subsidiary or related company of a group with RM1 million or more in turnover, you''re in scope from 1 July regardless of your own individual size. Group structure, not standalone revenue, is what determines whether you''re caught here.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Official source: LHDN — MyInvois / e-Invoice</a></p>', 'https://www.hasil.gov.my/en/e-invoice', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-01-malaysia-related-company-rule-preview', id FROM countries WHERE name_en = 'Malaysia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-malaysia-related-company-rule-preview', 'en', 'Malaysia — related companies of RM1m+ groups now in scope', 'Malaysia''s MyInvois related-company rule takes effect 1 July, catching subsidiaries of RM1 million+ groups regardless of their own individual revenue.', '<h3>🇲🇾 Malaysia — related companies of RM1m+ groups now in scope</h3><p>Here''s the one most likely to catch a business off guard: even if your own revenue is well under Malaysia''s thresholds, if you''re a subsidiary or related company of a group with RM1 million or more in turnover, you''re in scope from 1 July regardless of your own individual size. Group structure, not standalone revenue, is what determines whether you''re caught here.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Official source: LHDN — MyInvois / e-Invoice</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-01-uae-voluntary-pilot-preview', '2026-06-01', '2026-06', 'The UAE opens a voluntary e-invoicing pilot from 1 July, letting businesses test ASP connectivity ahead of the January 2027 mandatory phases.', '<h3>🇦🇪 UAE — voluntary e-invoicing pilot opens</h3><p>Ahead of the mandatory phases starting January 2027, the UAE opens voluntary participation this date — letting businesses test Accredited Service Provider connectivity and the PINT AE format risk-free before penalties apply. Given the ASP appointment deadline for large businesses lands in October, using this pilot window well ahead of that is genuinely the sensible order to do things in.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Official source: UAE Ministry of Finance — eInvoicing</a></p><p><strong>What this means for your team:</strong> if any of these four apply to you, this is the month to actually finish testing, not start it. 1 July arrives fast, and none of these four give much grace period once the date passes.</p>', 'https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-01-uae-voluntary-pilot-preview', id FROM countries WHERE name_en = 'United Arab Emirates';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-uae-voluntary-pilot-preview', 'en', 'UAE — voluntary e-invoicing pilot opens', 'The UAE opens a voluntary e-invoicing pilot from 1 July, letting businesses test ASP connectivity ahead of the January 2027 mandatory phases.', '<h3>🇦🇪 UAE — voluntary e-invoicing pilot opens</h3><p>Ahead of the mandatory phases starting January 2027, the UAE opens voluntary participation this date — letting businesses test Accredited Service Provider connectivity and the PINT AE format risk-free before penalties apply. Given the ASP appointment deadline for large businesses lands in October, using this pilot window well ahead of that is genuinely the sensible order to do things in.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Official source: UAE Ministry of Finance — eInvoicing</a></p><p><strong>What this means for your team:</strong> if any of these four apply to you, this is the month to actually finish testing, not start it. 1 July arrives fast, and none of these four give much grace period once the date passes.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-01-australia-peppol-threshold-live', '2026-07-01', '2026-07', 'Australia''s 30% Peppol threshold for federal invoices is now in force, with quarterly progress reporting to the Australian Peppol Authority.', '<h3>🇦🇺 Australia — 30% Peppol threshold now in force</h3><p>Federal agencies must now have at least 30% of received supplier invoices flowing through Peppol, with quarterly progress reporting to the Australian Peppol Authority. If you supply into this space and haven''t confirmed your invoicing is Peppol-enabled, that''s no longer a "soon" task — it''s an active compliance gap.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Official source: ATO — About eInvoicing</a></p>', 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-01-australia-peppol-threshold-live', id FROM countries WHERE name_en = 'Australia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-australia-peppol-threshold-live', 'en', 'Australia — 30% Peppol threshold now in force', 'Australia''s 30% Peppol threshold for federal invoices is now in force, with quarterly progress reporting to the Australian Peppol Authority.', '<h3>🇦🇺 Australia — 30% Peppol threshold now in force</h3><p>Federal agencies must now have at least 30% of received supplier invoices flowing through Peppol, with quarterly progress reporting to the Australian Peppol Authority. If you supply into this space and haven''t confirmed your invoicing is Peppol-enabled, that''s no longer a "soon" task — it''s an active compliance gap.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Official source: ATO — About eInvoicing</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-01-denmark-small-business-bookkeeping-live', '2026-07-01', '2026-07', 'Denmark''s Bookkeeping Act digital requirements are now active for small businesses on custom systems above the DKK 300,000 threshold.', '<h3>🇩🇰 Denmark — small businesses on custom systems now in scope</h3><p>The Bookkeeping Act''s digital requirements now apply to small businesses and sole proprietorships over the DKK 300,000 two-year threshold using non-registered systems, including a requirement to maintain 5-year digital records with automated off-site backup.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Official source: Erhvervsstyrelsen (Danish Business Authority)</a></p>', 'https://erhvervsstyrelsen.dk', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-01-denmark-small-business-bookkeeping-live', id FROM countries WHERE name_en = 'Denmark';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-denmark-small-business-bookkeeping-live', 'en', 'Denmark — small businesses on custom systems now in scope', 'Denmark''s Bookkeeping Act digital requirements are now active for small businesses on custom systems above the DKK 300,000 threshold.', '<h3>🇩🇰 Denmark — small businesses on custom systems now in scope</h3><p>The Bookkeeping Act''s digital requirements now apply to small businesses and sole proprietorships over the DKK 300,000 two-year threshold using non-registered systems, including a requirement to maintain 5-year digital records with automated off-site backup.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Official source: Erhvervsstyrelsen (Danish Business Authority)</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-01-malaysia-related-company-rule-live', '2026-07-01', '2026-07', 'Malaysia''s MyInvois related-company rule is now active, bringing subsidiaries of RM1 million+ groups into scope.', '<h3>🇲🇾 Malaysia — related-company rule now active</h3><p>Subsidiaries and related companies of RM1 million+ groups are now within MyInvois'' scope, regardless of their own individual revenue. Worth a final check of your group structure today if you haven''t already confirmed your status.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Official source: LHDN — MyInvois / e-Invoice</a></p>', 'https://www.hasil.gov.my/en/e-invoice', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-01-malaysia-related-company-rule-live', id FROM countries WHERE name_en = 'Malaysia';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-malaysia-related-company-rule-live', 'en', 'Malaysia — related-company rule now active', 'Malaysia''s MyInvois related-company rule is now active, bringing subsidiaries of RM1 million+ groups into scope.', '<h3>🇲🇾 Malaysia — related-company rule now active</h3><p>Subsidiaries and related companies of RM1 million+ groups are now within MyInvois'' scope, regardless of their own individual revenue. Worth a final check of your group structure today if you haven''t already confirmed your status.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Official source: LHDN — MyInvois / e-Invoice</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-01-uae-voluntary-pilot-live', '2026-07-01', '2026-07', 'The UAE''s voluntary e-invoicing pilot is now open, ahead of the January 2027 mandatory phases and October''s ASP appointment deadline for larger businesses.', '<h3>🇦🇪 UAE — voluntary pilot now open</h3><p>Businesses can now test Accredited Service Provider connectivity and the PINT AE format ahead of the January 2027 mandatory phases — genuinely worth starting immediately given the ASP appointment deadline for larger businesses falls in October.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Official source: UAE Ministry of Finance — eInvoicing</a></p>', 'https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-01-uae-voluntary-pilot-live', id FROM countries WHERE name_en = 'United Arab Emirates';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-uae-voluntary-pilot-live', 'en', 'UAE — voluntary pilot now open', 'The UAE''s voluntary e-invoicing pilot is now open, ahead of the January 2027 mandatory phases and October''s ASP appointment deadline for larger businesses.', '<h3>🇦🇪 UAE — voluntary pilot now open</h3><p>Businesses can now test Accredited Service Provider connectivity and the PINT AE format ahead of the January 2027 mandatory phases — genuinely worth starting immediately given the ASP appointment deadline for larger businesses falls in October.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Official source: UAE Ministry of Finance — eInvoicing</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-01-poland-bank-transfer-reference-preview', '2026-07-01', '2026-07', 'A preview of Poland''s 1 August requirement to include KSeF invoice numbers on bank transfer references — an easy detail for treasury teams to miss.', '<h3>What we''re watching for August</h3><p>Poland''s KSeF invoice-number-on-bank-transfer requirement takes effect on 1 August — a small but easy-to-miss detail if your treasury/payments team isn''t already looped into your e-invoicing rollout. We''ll cover it properly next issue, with the official KSeF link as always.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">As always, the country Deep Dives have the full technical detail behind each of these if you need to brief your team beyond this summary.</p>', NULL, 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-01-poland-bank-transfer-reference-preview', id FROM countries WHERE name_en = 'Poland';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-poland-bank-transfer-reference-preview', 'en', 'What we''re watching for August', 'A preview of Poland''s 1 August requirement to include KSeF invoice numbers on bank transfer references — an easy detail for treasury teams to miss.', '<h3>What we''re watching for August</h3><p>Poland''s KSeF invoice-number-on-bank-transfer requirement takes effect on 1 August — a small but easy-to-miss detail if your treasury/payments team isn''t already looped into your e-invoicing rollout. We''ll cover it properly next issue, with the official KSeF link as always.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">As always, the country Deep Dives have the full technical detail behind each of these if you need to brief your team beyond this summary.</p>');
